import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent, type Skill } from "../../types";
import { EventInfo } from "./EventInfo";
import { OrderedBlockEventInfo, type OrderedBlockLifecycleEvent } from "./OrderedBlockEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const travelNotice: Skill = {
  id: "travel_notice",
  name: "Travel Notice",
  description: "Skill-level description that must not appear on a block event.",
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [],
  blocks: {
    submit: {
      ordered_block_id: "travel_notice__submit",
      complete_when: null,
      steps: [],
    },
  },
  referenced_skills: [],
  tool_names: [],
  hidden: false,
};

function enteredEvent(id = "e1"): OrderedBlockLifecycleEvent {
  return {
    id,
    conversationEventType: ConversationEventType.OrderedBlockEntered,
    name: "ordered_block_entered",
    actionText: "",
    skillId: "travel_notice",
    blockId: "submit",
    stepId: "",
    slotValue: null,
    timestamp: "2020-01-01T00:00:00.000Z",
    originalTimestamp: 100,
    metadata: { parseData: {} },
    __typename: "ConversationEvent",
  };
}

describe("OrderedBlockEventInfo", () => {
  it("is selected for a known ordered-block lifecycle event", () => {
    renderWithProviders(<EventInfo event={enteredEvent()} onClose={() => undefined} flows={[]} />, {
      initialStoreState: { skillCatalog: { travel_notice: travelNotice } },
    });

    expect(screen.getByRole("heading", { name: "Block entered" })).toBeInTheDocument();
    expect(screen.getByText("travel_notice")).toBeInTheDocument();
    expect(screen.getByText("submit")).toBeInTheDocument();
    expect(screen.getByText("Travel Notice")).toBeInTheDocument();
    expect(
      screen.queryByText("Skill-level description that must not appear on a block event."),
    ).toBeNull();
  });

  it("keeps the block panel when the catalog has not loaded yet", () => {
    renderWithProviders(<EventInfo event={enteredEvent()} onClose={() => undefined} flows={[]} />, {
      initialStoreState: { skillCatalog: null },
    });

    expect(screen.getByRole("heading", { name: "Block entered" })).toBeInTheDocument();
    expect(screen.getByText("travel_notice")).toBeInTheDocument();
    expect(screen.getByText("submit")).toBeInTheDocument();
    expect(screen.queryByRole("heading", { name: "Event" })).toBeNull();
    expect(screen.queryByText("Travel Notice")).toBeNull();
  });

  it("omits step id on entered even when the payload carries one", () => {
    const event: OrderedBlockLifecycleEvent = {
      ...enteredEvent(),
      stepId: "should_not_show",
    };
    renderWithProviders(<OrderedBlockEventInfo event={event} onClose={() => undefined} />, {
      initialStoreState: { skillCatalog: { travel_notice: travelNotice } },
    });

    expect(screen.queryByText("should_not_show")).toBeNull();
  });

  it("shows the step id for completed", () => {
    const event: OrderedBlockLifecycleEvent = {
      ...enteredEvent(),
      conversationEventType: ConversationEventType.OrderedBlockCompleted,
      stepId: "confirm_dates",
    };
    renderWithProviders(<OrderedBlockEventInfo event={event} onClose={() => undefined} />, {
      initialStoreState: { skillCatalog: { travel_notice: travelNotice } },
    });

    expect(screen.getByRole("heading", { name: "Block completed" })).toBeInTheDocument();
    expect(screen.getByText("confirm_dates")).toBeInTheDocument();
  });
});

describe("EventInfo ordered-block routing", () => {
  it("does not use the block panel when an OrderedBlock* event has no block id", () => {
    const event: ConversationEvent = {
      ...enteredEvent(),
      blockId: undefined,
    };
    renderWithProviders(<EventInfo event={event} onClose={() => undefined} flows={[]} />, {
      initialStoreState: { skillCatalog: { travel_notice: travelNotice } },
    });

    expect(screen.queryByRole("heading", { name: "Block entered" })).toBeNull();
    expect(screen.getByRole("heading", { name: "Event" })).toBeInTheDocument();
  });
});
